let BOARD_FACE_LIGHT = { dataURL: `data:image/svg+xml;base64,${btoa(`<svg xmlns="http://www.w3.org/2000/svg" width="192" height="192" viewBox="0 0 192 192"><defs><filter id="light-ground"><feComponentTransfer><feFuncR type="linear" slope="0.965"/><feFuncG type="linear" slope="0.965"/><feFuncB type="linear" slope="0.965"/></feComponentTransfer></filter></defs><image width="192" height="192" href="${BOARD_FACE.dataURL}" filter="url(#light-ground)"/></svg>`)}`, mimeType: 'image/svg+xml' };
