MATILDA_SHOTS.kissSoft = "data:image/svg+xml;base64,";
MATILDA_SHOTS.kissPuckered = "data:image/svg+xml;base64,";
const BOARD_SHOTS = {"listening":"data:image/webp;base64,","smile":"data:image/webp;base64,","softSmile":"data:image/webp;base64,","tiltSmile":"data:image/webp;base64,","wink":"data:image/webp;base64,","kissSoft":"data:image/webp;base64,","kissPuckered":"data:image/webp;base64,"};

const PORTRAIT_MARKER = /^\s*<!--\s*matilda:(listening|smile|softSmile|tiltSmile|wink|kissSoft|kissPuckered)\s*-->\s*/;
