const PORTRAIT_INSTRUCTIONS = "Choose a portrait matching each reply by starting with <!--matilda:listening-->, <!--matilda:smile-->, <!--matilda:softSmile-->, <!--matilda:tiltSmile-->, <!--matilda:wink-->, <!--matilda:kissSoft--> or <!--matilda:kissPuckered-->. Use listening for serious replies, a smile for warmth or good news, wink for play, and kisses for affection when it fits. This metadata is hidden from the note and speech. ";
for (const expression of ['kissSoft', 'kissPuckered']) MATILDA_SHOTS_LIGHT[expression] = lightAvatar(MATILDA_SHOTS[expression]);
