FACE_DATA_URL = MATILDA_SHOTS.listening; FACE_DATA_URL_LIGHT = MATILDA_SHOTS_LIGHT.listening;
BOARD_FACE = { dataURL: FACE_DATA_URL, mimeType: 'image/svg+xml' };
